import * as React from "react";

export function useDiscardChangesGuard({
  isDirty,
  onDiscard
}: {
  isDirty: boolean;
  onDiscard: () => void;
}) {
  const [isDiscardDialogOpen, setIsDiscardDialogOpen] = React.useState(false);
  const requestDiscard = React.useCallback(() => {
    if (isDirty) {
      setIsDiscardDialogOpen(true);
      return;
    }
    onDiscard();
  }, [isDirty, onDiscard]);
  const confirmDiscard = React.useCallback(() => {
    setIsDiscardDialogOpen(false);
    onDiscard();
  }, [onDiscard]);
  return {
    confirmDiscard,
    isDiscardDialogOpen,
    requestDiscard,
    setIsDiscardDialogOpen,
    discardDialogProps: {
      open: isDiscardDialogOpen,
      onOpenChange: setIsDiscardDialogOpen,
      onDiscard: confirmDiscard
    }
  };
}

import * as React from "react";

const MOBILE_BREAKPOINT = 768;

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined);

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    };
    mql.addEventListener("change", onChange);
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    return () => mql.removeEventListener("change", onChange);
  }, []);

  return !!isMobile;
}

/** Storage keys the app theme reads: the shared light, dark or system preference, the named theme per scheme, and a demo preview. */
export const v4ThemeStorage = {
  shared: "infisical-theme",
  preferred: "v4-theme",
  override: "v4-theme-override"
} as const;

/** A live org route: /v4/organizations/<id> with an id other than the demo org. */
export const v4LiveOrgPath = /^\/v4\/organizations\/(?!demo(?:\/|$))[^/]+/;

import { v4LiveOrgPath, v4ThemeStorage } from "./boot-theme-keys";
import { defaultV4Theme, toV4Theme, v4ThemeScheme } from "./theme-registry";
import type { V4Scheme } from "./themes";

export { v4LiveOrgPath, v4ThemeStorage };

const read = (storage: () => Storage, key: string) => {
  try {
    return storage().getItem(key);
  } catch {
    return null;
  }
};

/**
 * The v4 theme for a location, from storage alone, for UI that renders before V4Scope and the
 * React theme provider: a ?theme= or session preview outside live orgs, else the person's named
 * theme for the scheme their shared preference resolves to.
 */
export const readV4BootTheme = (
  location: Pick<Location, "pathname" | "search"> = window.location
): string => {
  if (!v4LiveOrgPath.test(location.pathname)) {
    const preview =
      toV4Theme(new URLSearchParams(location.search).get("theme")) ??
      toV4Theme(read(() => window.sessionStorage, v4ThemeStorage.override));
    if (preview) return preview;
  }
  const shared = read(() => window.localStorage, v4ThemeStorage.shared);
  const choice = shared === "light" || shared === "dark" || shared === "system" ? shared : "dark";
  const systemLight =
    choice === "system" && window.matchMedia("(prefers-color-scheme: light)").matches;
  const scheme: V4Scheme = choice === "light" || systemLight ? "light" : "dark";
  let preferred: Partial<Record<V4Scheme, unknown>> = {};
  try {
    preferred = JSON.parse(read(() => window.localStorage, v4ThemeStorage.preferred) || "{}");
  } catch {
    preferred = {};
  }
  const named = toV4Theme(preferred[scheme]);
  return named && v4ThemeScheme(named) === scheme ? named : defaultV4Theme[scheme];
};

import * as React from "react";

/** Data attribute name to the selector that turns it on. */
export type DescendantFlags = Readonly<Record<string, string>>;

type Watch = {
  /** Attributes whose changes below the element can flip a flag. */
  attributes?: readonly string[];
  /** false watches only the element's own children. */
  subtree?: boolean;
  /** Re-checks on focus moving in or out, for :focus-visible selectors. */
  focus?: boolean;
  /** Flags set on each element below that matches the selector, instead of on the element itself. */
  marks?: DescendantFlags;
};

const setFlag = (element: Element, name: string, on: boolean) => {
  if (element.hasAttribute(name) !== on) element.toggleAttribute(name, on);
};

export const assignRef = <T>(ref: React.Ref<T> | undefined, value: T | null) => {
  if (typeof ref === "function") ref(value);
  else if (ref) {
    const target = ref;
    target.current = value;
  }
};

/**
 * Mirrors state the component does not own, such as a slotted control's focus, invalid or disabled
 * state or which slots a caller composed, onto data attributes, re-checked only on this element's own
 * focus changes and mutations. A :has() selector instead re-checks on every DOM change in the
 * document, so one cell update in a large table relayouts the page. Returns the ref to attach;
 * flags and watch must be module constants.
 */
export function useDescendantFlags<T extends Element>(
  flags: DescendantFlags,
  watch: Watch = {},
  forwardedRef?: React.Ref<T>
) {
  const [node, setNode] = React.useState<T | null>(null);
  const ref = React.useCallback(
    (element: T | null) => {
      setNode(element);
      assignRef(forwardedRef, element);
    },
    [forwardedRef]
  );
  const { attributes, subtree = true, focus = false, marks } = watch;
  const sync = React.useCallback(() => {
    if (!node) return;
    Object.entries(flags).forEach(([name, selector]) =>
      setFlag(node, name, node.querySelector(selector) !== null)
    );
    if (marks)
      Object.entries(marks).forEach(([name, selector]) => {
        const hits = new Set(node.querySelectorAll(selector));
        node.querySelectorAll(`[${name}]`).forEach((element) => {
          if (!hits.has(element)) element.removeAttribute(name);
        });
        hits.forEach((element) => setFlag(element, name, true));
      });
  }, [node, flags, marks]);
  React.useLayoutEffect(sync);
  React.useLayoutEffect(() => {
    if (!node) return undefined;
    const observer = new MutationObserver(sync);
    observer.observe(node, {
      childList: true,
      subtree,
      ...(attributes?.length ? { attributes: true, attributeFilter: [...attributes] } : {})
    });
    const later = () => queueMicrotask(sync);
    if (focus) {
      node.addEventListener("focusin", later);
      node.addEventListener("focusout", later);
    }
    return () => {
      observer.disconnect();
      node.removeEventListener("focusin", later);
      node.removeEventListener("focusout", later);
    };
  }, [node, sync, subtree, attributes, focus]);
  return ref;
}

import * as React from "react";

export type FieldControlAttributes = Pick<
  React.AriaAttributes,
  "aria-describedby" | "aria-invalid" | "aria-labelledby"
> & { id?: string };
export const FieldControlContext = React.createContext<FieldControlAttributes>({});
export function useFieldControlAttributes(props: FieldControlAttributes): FieldControlAttributes {
  const field = React.useContext(FieldControlContext);
  return {
    id: props.id ?? field.id,
    "aria-labelledby": props["aria-labelledby"] ?? field["aria-labelledby"],
    "aria-invalid": field["aria-invalid"] || props["aria-invalid"],
    "aria-describedby":
      [field["aria-describedby"], props["aria-describedby"]].filter(Boolean).join(" ") || undefined
  };
}

import * as React from "react";

const FrameContext = React.createContext(false);

/** Marks a subtree as inside a framed container, or, with framed false, starts a fresh surface such as an overlay. */
export function FrameScope({ framed, children }: { framed: boolean; children: React.ReactNode }) {
  return <FrameContext value={framed}>{children}</FrameContext>;
}

/**
 * Whether this primitive renders inside a framed container, where it drops its own frame so two frames never nest.
 * Pass the variant the caller asked for to warn in development when an explicit framed variant is dropped.
 */
export function useInFrame(component: string, requested?: string): boolean {
  const inFrame = React.useContext(FrameContext);
  const forced = inFrame && requested === "framed";
  React.useEffect(() => {
    if (import.meta.env.DEV && forced)
      console.warn(
        `${component} variant="framed" renders inside another framed container, so it drops to its frameless treatment. Remove the variant.`
      );
  }, [component, forced]);
  return inFrame;
}

/**
 * The input that started the current interaction. A keydown makes it keyboard and a pointerdown
 * makes it pointer; Escape keeps it, so closing a menu returns focus with the modality that opened it.
 */
let modality: "keyboard" | "pointer" = "pointer";
if (typeof document !== "undefined") {
  document.addEventListener(
    "keydown",
    (event) => {
      if (event.key !== "Escape") modality = "keyboard";
    },
    true
  );
  document.addEventListener(
    "pointerdown",
    () => {
      modality = "pointer";
    },
    true
  );
}

export const keyboardModality = () => modality === "keyboard";

export type InvisibleCharacterSummary = {
  codePoint: string;
  label: string;
  count: number;
};

export type SecretValuePart = {
  text: string;
  isSuspicious: boolean;
};

const ALLOWED_WHITESPACE = new Set([" ", "\t", "\n", "\r"]);

const SUSPICIOUS_CATEGORY_REGEX = /^[\p{Cc}\p{Cf}\p{Zs}\p{Zl}\p{Zp}]$/u;

const EMOJI_SEQUENCE_REGEX =
  /\p{Extended_Pictographic}(?:\p{Emoji_Modifier}|\uFE0F)*(?:\u200D\p{Extended_Pictographic}(?:\p{Emoji_Modifier}|\uFE0F)*)+|\u{1F3F4}[\u{E0020}-\u{E007E}]+\u{E007F}/gu;

export const isSuspiciousCharacter = (char: string) =>
  !ALLOWED_WHITESPACE.has(char) && SUSPICIOUS_CATEGORY_REGEX.test(char);

const getCharacterLabel = (char: string) => {
  if (/\p{Bidi_Control}/u.test(char)) return "Bidirectional control";
  if (/\p{Cc}/u.test(char)) return "Control character";
  if (/\p{Zs}/u.test(char)) return "Unicode space";
  if (/\p{Zl}/u.test(char)) return "Line separator";
  if (/\p{Zp}/u.test(char)) return "Paragraph separator";
  return "Formatting character";
};

export const splitSuspiciousCharacters = (value: string): SecretValuePart[] => {
  const parts: SecretValuePart[] = [];

  const pushPlain = (text: string) => {
    const last = parts[parts.length - 1];
    if (last && !last.isSuspicious) {
      last.text += text;
    } else {
      parts.push({ text, isSuspicious: false });
    }
  };

  const scan = (text: string) => {
    Array.from(text).forEach((char) => {
      if (isSuspiciousCharacter(char)) {
        parts.push({ text: char, isSuspicious: true });
      } else {
        pushPlain(char);
      }
    });
  };

  let offset = 0;
  Array.from(value.matchAll(EMOJI_SEQUENCE_REGEX)).forEach((match) => {
    const index = match.index ?? 0;
    scan(value.slice(offset, index));
    pushPlain(match[0]);
    offset = index + match[0].length;
  });
  scan(value.slice(offset));

  return parts;
};

export const getInvisibleCharacterSummary = (value: string): InvisibleCharacterSummary[] => {
  const summary = new Map<number, InvisibleCharacterSummary>();

  splitSuspiciousCharacters(value).forEach(({ text, isSuspicious }) => {
    if (!isSuspicious) return;
    const code = text.codePointAt(0) ?? 0;
    const entry = summary.get(code);
    if (entry) {
      entry.count += 1;
      return;
    }
    summary.set(code, {
      codePoint: `U+${code.toString(16).toUpperCase().padStart(4, "0")}`,
      label: getCharacterLabel(text),
      count: 1
    });
  });

  return Array.from(summary.values());
};

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import { fade, snap, spring } from "./motion";

export const LIST_HIGHLIGHT_ITEM =
  '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"], [cmdk-item], [data-sidebar-target]';
const ACTIVE =
  '[data-highlighted], [cmdk-item][data-selected="true"], [role="option"][data-active]';
const CURRENT =
  '[data-current], [aria-current="page"], [role="option"][data-state="checked"], [role="menuitemradio"][aria-checked="true"]';
const HOLDS = "[data-holds-current]";
const EXPANDED = '[aria-haspopup]:is([aria-expanded="true"], [data-state="open"])';
const DANGER = '[data-danger], [data-variant="destructive"]';
const KEYS = ["ArrowDown", "ArrowUp", "Home", "End", "PageUp", "PageDown"];

type Thumb = {
  x: number;
  y: number;
  width: number;
  height: number;
  radius: string;
  danger: boolean;
  target: number;
  visible: boolean;
  placed: boolean;
  jump: boolean;
  first: boolean;
};
const hidden: Thumb = {
  x: 0,
  y: 0,
  width: 0,
  height: 0,
  radius: "0px",
  danger: false,
  target: -1,
  visible: false,
  placed: false,
  jump: true,
  first: true
};

const blocked = (element: HTMLElement) =>
  element.hasAttribute("disabled") ||
  element.getAttribute("aria-disabled") === "true" ||
  (element.hasAttribute("data-disabled") && element.getAttribute("data-disabled") !== "false");

/** Offsets inside the list, through offsetParent, so open animations (scale, translate) never skew them. */
const offsetIn = (element: HTMLElement, list: HTMLElement) => {
  let x = 0;
  let y = 0;
  let node: HTMLElement | null = element;
  while (node && node !== list) {
    x += node.offsetLeft;
    y += node.offsetTop;
    const parent = node.offsetParent as HTMLElement | null;
    if (parent && parent !== list && list.contains(parent)) {
      x += parent.clientLeft - parent.scrollLeft;
      y += parent.clientTop - parent.scrollTop;
    }
    node = parent && list.contains(parent) ? parent : null;
  }
  return { x, y };
};

/**
 * Two translucent thumbs per list. The hover thumb follows the pointer and the keyboard's active
 * row and stays on the last row while the pointer is anywhere in the list. A row whose popover,
 * flyout or submenu is open (aria-haspopup with aria-expanded="true" or data-state="open"; a
 * wrapping Tooltip overwrites data-state, so aria-expanded is the reliable signal) pins the hover
 * thumb until it closes, even after the pointer leaves for the popover. The selection thumb
 * rests on the current row and shows only while the hover thumb is hidden. Arrow keys in a field
 * outside the list that names it with aria-controls move the hover thumb too. Render it as the list's
 * last child; it measures its parent.
 */
export function ListHighlight() {
  const self = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const [hover, setHover] = React.useState<Thumb>(hidden);
  const [selection, setSelection] = React.useState<Thumb>(hidden);

  React.useLayoutEffect(() => {
    const list = self.current?.parentElement;
    if (!list) return undefined;
    list.setAttribute("data-list-highlight", "");
    if (getComputedStyle(list).position === "static") list.style.position = "relative";
    const zone =
      (list.closest("[data-radix-popper-content-wrapper]")
        ?.firstElementChild as HTMLElement | null) ?? list;
    let hovered: HTMLElement | null = null;
    let keyboard = false;
    let inside = false;
    let frame = 0;
    const own = (element: Element | null) =>
      element instanceof HTMLElement && element.closest("[data-list-highlight]") === list
        ? element
        : null;
    const items = () =>
      [...list.querySelectorAll(LIST_HIGHLIGHT_ITEM)].map(own).filter(Boolean) as HTMLElement[];
    const first = (selector: string) => items().find((item) => item.matches(selector)) ?? null;
    const measureOne = (
      target: HTMLElement | null,
      set: React.Dispatch<React.SetStateAction<Thumb>>
    ) => {
      if (!target || !target.isConnected) {
        set((current) => (current.visible ? { ...current, visible: false, jump: false } : current));
        return;
      }
      const { x, y } = offsetIn(target, list);
      const all = items();
      set((current) => ({
        x,
        y,
        width: target.offsetWidth,
        height: target.offsetHeight,
        radius: getComputedStyle(target).borderRadius,
        danger: target.matches(DANGER),
        target: all.indexOf(target),
        visible: true,
        placed: true,
        jump: !current.placed || !current.visible,
        first: !current.placed
      }));
    };
    const measure = () => {
      frame = 0;
      const current = first(CURRENT) ?? first(HOLDS);
      const expanded = first(EXPANDED);
      let hoverTarget: HTMLElement | null = expanded && !blocked(expanded) ? expanded : null;
      if (!hoverTarget && keyboard) hoverTarget = first(ACTIVE) ?? current;
      else if (!hoverTarget && inside && hovered?.isConnected) hoverTarget = hovered;
      measureOne(hoverTarget, setHover);
      measureOne(hoverTarget ? null : current, setSelection);
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };
    const over = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      inside = true;
      const item = own(
        event.target instanceof Element ? event.target.closest(LIST_HIGHLIGHT_ITEM) : null
      );
      if (item && !blocked(item)) {
        hovered = item;
        keyboard = false;
      }
      schedule();
    };
    const leave = () => {
      inside = false;
      hovered = null;
      if (!list.contains(document.activeElement)) keyboard = false;
      schedule();
    };
    const controls = (target: EventTarget | null) =>
      Boolean(list.id) &&
      target instanceof Element &&
      target.getAttribute("aria-controls") === list.id;
    const key = (event: KeyboardEvent) => {
      if (!KEYS.includes(event.key)) return;
      if (
        !list.contains(document.activeElement) &&
        !list.contains(event.target as Node) &&
        !list.closest(":focus-within") &&
        !controls(event.target)
      )
        return;
      keyboard = true;
      schedule();
    };
    const focusOut = (event: FocusEvent) => {
      if (event.relatedTarget instanceof Node && list.contains(event.relatedTarget)) return;
      keyboard = false;
      schedule();
    };
    zone.addEventListener("pointerover", over);
    zone.addEventListener("pointerleave", leave);
    list.addEventListener("focusout", focusOut);
    list.addEventListener("animationend", schedule);
    list.addEventListener("transitionend", schedule);
    document.addEventListener("keydown", key, true);
    const resize = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(schedule);
    const watchItems = () => {
      if (!resize) return;
      resize.disconnect();
      resize.observe(list);
      items().forEach((item) => resize.observe(item));
    };
    watchItems();
    const mutations = new MutationObserver((records) => {
      if (records.some((record) => record.type === "childList")) watchItems();
      schedule();
    });
    mutations.observe(list, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: [
        "data-highlighted",
        "data-selected",
        "data-active",
        "data-current",
        "aria-current",
        "data-holds-current",
        "data-state",
        "aria-expanded",
        "aria-checked"
      ]
    });
    measure();
    return () => {
      cancelAnimationFrame(frame);
      zone.removeEventListener("pointerover", over);
      zone.removeEventListener("pointerleave", leave);
      list.removeEventListener("focusout", focusOut);
      list.removeEventListener("animationend", schedule);
      list.removeEventListener("transitionend", schedule);
      document.removeEventListener("keydown", key, true);
      resize?.disconnect();
      mutations.disconnect();
      list.removeAttribute("data-list-highlight");
    };
  }, []);

  const thumb = (state: Thumb, kind: "hover" | "selection") => (
    <motion.span
      aria-hidden
      data-slot="list-highlight"
      data-thumb={kind}
      data-visible={state.visible || undefined}
      data-target={state.target}
      data-danger={state.danger || undefined}
      initial={false}
      style={{ borderRadius: state.radius }}
      animate={{
        x: state.x,
        y: state.y,
        width: state.width,
        height: state.height,
        opacity: state.visible ? 1 : 0
      }}
      transition={{
        default: state.jump || reduced ? snap : spring.moderate,
        opacity: reduced || state.first ? snap : fade.enter
      }}
    />
  );
  return (
    <span ref={self} data-slot="list-highlight-layer" style={{ display: "contents" }}>
      {thumb(selection, "selection")}
      {thumb(hover, "hover")}
    </span>
  );
}

import * as React from "react";
import {
  ContextMenu as ContextMenuPrimitive,
  DropdownMenu as DropdownMenuPrimitive
} from "radix-ui";

/** Which menu a shared item renders in, so the DropdownMenu items also render inside a ContextMenu. */
export const MenuKindContext = React.createContext<"dropdown" | "context">("dropdown");

/** The Radix primitives for the menu an item sits in. Both share the same Menu parts and props. */
export const useMenuPrimitive = () =>
  (React.useContext(MenuKindContext) === "context"
    ? ContextMenuPrimitive
    : DropdownMenuPrimitive) as typeof DropdownMenuPrimitive;

import type { Transition } from "motion/react";

/** Millisecond mirrors of the motion tokens, for timers that wait out a motion. Guarded by motion.test.ts. */
export const motionMs = {
  fast: 80,
  moderate: 160,
  slow: 240,
  exit: { fast: 32, moderate: 120, slow: 96 }
} as const;

const seconds = (ms: number) => ms / 1000;

/** Enters and moves, by the size of what moves. Critically damped except the slow tier. */
export const spring = {
  fast: { type: "spring", duration: seconds(motionMs.fast), bounce: 0 },
  moderate: { type: "spring", duration: seconds(motionMs.moderate), bounce: 0 },
  slow: { type: "spring", duration: seconds(motionMs.slow), bounce: 0.12 }
} as const satisfies Record<string, Transition>;

/** Leaving, one tier quicker than entering. */
export const exit = {
  fast: { type: "tween", duration: seconds(motionMs.exit.fast), ease: "easeOut" },
  moderate: { type: "tween", duration: seconds(motionMs.exit.moderate), ease: "easeOut" },
  slow: { type: "tween", duration: seconds(motionMs.exit.slow), ease: "easeOut" }
} as const satisfies Record<string, Transition>;

/** Opacity and color fades that carry state, so they stay when travel is reduced. */
export const fade = {
  enter: { type: "tween", duration: seconds(motionMs.fast), ease: "easeOut" },
  exit: exit.fast
} as const satisfies Record<string, Transition>;

export const snap = { duration: 0 } as const satisfies Transition;

import * as React from "react";

export const OverlayPendingContext = React.createContext(false);

export const useOverlayPending = () => React.useContext(OverlayPendingContext);

const isToastTarget = (target: EventTarget | null) =>
  target instanceof Element &&
  Boolean(target.closest("[data-sonner-toaster], [data-slot='toast-stack']"));

// Toasts portal outside the modal layer, so a click on one would otherwise dismiss the overlay.
export function useDismissGuard<
  Outside extends Event & { target: EventTarget | null },
  Interact extends Event & { target: EventTarget | null }
>(
  pending: boolean,
  handlers: {
    onEscapeKeyDown: (event: KeyboardEvent) => void;
    onPointerDownOutside?: (event: Outside) => void;
    onInteractOutside?: (event: Interact) => void;
  }
) {
  const outside =
    <Target extends Event & { target: EventTarget | null }>(handler?: (event: Target) => void) =>
    (event: Target) => {
      if (pending || isToastTarget(event.target)) {
        event.preventDefault();
        return;
      }
      handler?.(event);
    };
  return {
    onEscapeKeyDown: (event: KeyboardEvent) => {
      if (pending) {
        event.preventDefault();
        return;
      }
      handlers.onEscapeKeyDown(event);
    },
    onPointerDownOutside: outside(handlers.onPointerDownOutside),
    onInteractOutside: outside(handlers.onInteractOutside)
  };
}

import * as React from "react";

type OverlayForm = React.ReactElement<React.ComponentProps<"form"> & { "data-slot"?: string }>;

type SectionTypes = {
  header: React.ElementType;
  subheader?: React.ElementType;
  body?: React.ElementType;
  footer: React.ElementType;
};

const flattenFragments = (children: React.ReactNode, prefix = ""): React.ReactNode[] =>
  React.Children.toArray(children).flatMap((child) => {
    if (React.isValidElement(child) && child.type === React.Fragment)
      return flattenFragments(
        (child.props as { children?: React.ReactNode }).children,
        `${prefix}${child.key}`
      );
    return React.isValidElement(child) && prefix
      ? [React.cloneElement(child, { key: `${prefix}${child.key}` })]
      : [child];
  });

/**
 * Splits overlay children into the shared scroll model: an optional pinned group (everything up to
 * the last subheader, or the last header too with pinHeader), one scroll region and the footers.
 * Fragments are unwrapped, so slots rendered behind a condition still count as direct children.
 * Returns null when no section slot is a direct child, so free-form content (a Sidebar in a Sheet, a
 * command palette) renders untouched. With lookThroughForm, a <form> that is the only child is looked
 * through: its children are split instead, and the result returns the form so Content renders the
 * sections inside it with display: contents, which keeps the same boxes as without the form.
 */
export const splitOverlaySections = (
  children: React.ReactNode,
  types: SectionTypes,
  {
    pinHeader = false,
    lookThroughForm = false
  }: { pinHeader?: boolean; lookThroughForm?: boolean } = {}
) => {
  const top = flattenFragments(children);
  const [only] = top;
  const form =
    lookThroughForm &&
    top.length === 1 &&
    React.isValidElement<OverlayForm["props"]>(only) &&
    only.type === "form"
      ? (only as OverlayForm)
      : undefined;
  const parts = form ? flattenFragments(form.props.children) : top;
  const is = (child: React.ReactNode, type?: React.ElementType) =>
    type !== undefined && React.isValidElement(child) && child.type === type;
  const slots = [types.header, types.subheader, types.body, types.footer];
  if (!parts.some((child) => slots.some((type) => is(child, type)))) return null;
  const rest = parts.filter((child) => !is(child, types.footer));
  const pinnedCount = rest.reduce<number>(
    (count, child, index) =>
      is(child, types.subheader) || (pinHeader && is(child, types.header)) ? index + 1 : count,
    0
  );
  return {
    pinned: rest.slice(0, pinnedCount),
    scroll: rest.slice(pinnedCount),
    footer: parts.filter((child) => is(child, types.footer)),
    form
  };
};

export const renderInForm = (
  form: OverlayForm | undefined,
  slot: string,
  layout: React.ReactNode
) => (form ? React.cloneElement(form, { "data-slot": slot }, layout) : layout);

import * as React from "react";

export type PresenceReport = (delta: number) => void;

/**
 * Counts descendants that report themselves through context, so a container styles itself from
 * React state instead of a :has() selector, which would make every DOM change below it relayout the document.
 */
export function usePresenceCount() {
  const [count, setCount] = React.useState(0);
  const report = React.useCallback<PresenceReport>(
    (delta) => setCount((value) => value + delta),
    []
  );
  return [count > 0, report] as const;
}

/** Reports to the nearest counter while active holds. */
export function useReportPresence(report: PresenceReport | null | undefined, active: boolean) {
  React.useLayoutEffect(() => {
    if (!active || !report) return undefined;
    report(1);
    return () => report(-1);
  }, [active, report]);
}

/**
 * Edge-aware scroll fade, ported from v3 useScrollEdges. Any element with data-scroll-fade="y",
 * "x" or "both" gets data-scroll-start-y / data-scroll-end-y (and -x) while more content sits
 * before or after the visible area; v4.css masks only those edges by size-scroll-fade. An area
 * that does not scroll gets no attribute and no fade. One document-level watcher serves every
 * V4Scope, so portaled menus and dialogs are covered too.
 */
const THRESHOLD = 1;
type Axis = "x" | "y";
const tracked = new WeakMap<HTMLElement, () => void>();
let started = 0;
let stop: (() => void) | null = null;

const axesOf = (element: HTMLElement): Axis[] => {
  const value = element.getAttribute("data-scroll-fade");
  if (value === "both") return ["x", "y"];
  return value === "x" ? ["x"] : ["y"];
};

const attach = (element: HTMLElement) => {
  if (tracked.has(element)) return;
  let frame = 0;
  const update = () => {
    frame = 0;
    const style = getComputedStyle(element);
    axesOf(element).forEach((axis) => {
      const overflow = axis === "y" ? style.overflowY : style.overflowX;
      if (overflow === "visible" || overflow === "clip") {
        element.removeAttribute(`data-scroll-start-${axis}`);
        element.removeAttribute(`data-scroll-end-${axis}`);
        return;
      }
      const offset = axis === "y" ? element.scrollTop : Math.abs(element.scrollLeft);
      const size = axis === "y" ? element.clientHeight : element.clientWidth;
      const total = axis === "y" ? element.scrollHeight : element.scrollWidth;
      element.toggleAttribute(`data-scroll-start-${axis}`, offset > THRESHOLD);
      element.toggleAttribute(`data-scroll-end-${axis}`, offset + size < total - THRESHOLD);
    });
  };
  const schedule = () => {
    if (!frame) frame = requestAnimationFrame(update);
  };
  element.addEventListener("scroll", schedule, { passive: true });
  const resize = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(schedule);
  resize?.observe(element);
  Array.from(element.children).forEach((child) => resize?.observe(child));
  const content = new MutationObserver(() => {
    Array.from(element.children).forEach((child) => resize?.observe(child));
    schedule();
  });
  content.observe(element, { childList: true, subtree: true, characterData: true });
  tracked.set(element, () => {
    cancelAnimationFrame(frame);
    element.removeEventListener("scroll", schedule);
    resize?.disconnect();
    content.disconnect();
  });
  update();
};

const sweep = (root: ParentNode) => {
  if (root instanceof HTMLElement && root.hasAttribute("data-scroll-fade")) attach(root);
  root.querySelectorAll<HTMLElement>("[data-scroll-fade]").forEach(attach);
};

/** Starts the shared watcher while at least one caller holds it; returns the release. */
export const watchScrollEdges = () => {
  if (typeof document === "undefined") return () => {};
  started += 1;
  if (started === 1) {
    sweep(document.body);
    const observer = new MutationObserver((records) => {
      records.forEach((record) => {
        record.addedNodes.forEach((node) => {
          if (node instanceof HTMLElement) sweep(node);
        });
        record.removedNodes.forEach((node) => {
          if (!(node instanceof HTMLElement)) return;
          [node, ...node.querySelectorAll<HTMLElement>("[data-scroll-fade]")].forEach((element) => {
            tracked.get(element)?.();
            tracked.delete(element);
          });
        });
        if (record.type === "attributes" && record.target instanceof HTMLElement)
          sweep(record.target);
      });
    });
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["data-scroll-fade"]
    });
    stop = () => observer.disconnect();
  }
  return () => {
    started -= 1;
    if (started === 0) stop?.();
  };
};

import { motion, useReducedMotion } from "motion/react";

import { exit, fade, snap, spring } from "./motion";
import type { IndicatorState } from "./use-measured-indicator";

/**
 * The raised chip behind the selected item. It moves on transforms and size with the moderate
 * spring, snaps on the first measure and under reduced motion, and cross-fades instead of travelling.
 */
export function SlidingIndicator({
  state,
  className
}: {
  state: IndicatorState;
  className?: string;
}) {
  const reduced = useReducedMotion();
  const travel = state.instant || reduced ? snap : spring.moderate;
  const appear = state.visible ? fade.enter : exit.moderate;
  return (
    <motion.span
      aria-hidden
      className={className}
      initial={false}
      animate={{
        x: state.x,
        y: state.y,
        width: state.width,
        height: state.height,
        opacity: state.visible ? 1 : 0
      }}
      transition={{
        default: travel,
        opacity: state.instant ? snap : appear
      }}
    />
  );
}

