import tokens from "../tokens.json";
import { legacyV4Themes, type V4Scheme, type V4ThemeDefinition } from "./themes";

export const v4Themes = tokens.themes.list as unknown as readonly V4ThemeDefinition[];

export const defaultV4Theme: Readonly<Record<V4Scheme, string>> = { light: "peach", dark: "dark" };

/** A theme id from a stored, URL or hard-coded value; legacy light and dark map to peach and dark. */
export const toV4Theme = (value: unknown): string | undefined => {
  if (typeof value !== "string") return undefined;
  const id = legacyV4Themes[value] ?? value;
  return v4Themes.some((theme) => theme.id === id) ? id : undefined;
};

export const v4ThemeScheme = (id: string): V4Scheme =>
  v4Themes.find((theme) => theme.id === id)?.scheme ?? "light";

export type V4Scheme = "light" | "dark";

export interface V4ThemeDefinition {
  id: string;
  name: string;
  scheme: V4Scheme;
  base?: V4Scheme;
  extends?: string;
  overrides: Readonly<Record<string, string>>;
}

export const legacyV4Themes: Readonly<Record<string, string>> = { light: "peach", dark: "dark" };

/** The theme and every theme it extends, nearest first, plus the base column the chain ends on. */
export const v4ThemeChain = (themes: readonly V4ThemeDefinition[], id: string) => {
  const chain: V4ThemeDefinition[] = [];
  let current = themes.find((theme) => theme.id === id);
  while (current) {
    if (chain.includes(current)) throw new Error(`Theme ${id} extends itself`);
    chain.push(current);
    if (current.base) return { chain, base: current.base };
    const parent = current.extends;
    current = themes.find((theme) => theme.id === parent);
    if (!current)
      throw new Error(`Theme ${chain[chain.length - 1].id} extends unknown theme ${parent}`);
  }
  throw new Error(`Unknown theme ${id}`);
};

/** A themed token's raw value in a theme: the nearest override, then the base column. */
export const v4ThemedValue = (
  themes: readonly V4ThemeDefinition[],
  id: string,
  name: string,
  value: Readonly<Record<string, string>>
) => {
  const { chain, base } = v4ThemeChain(themes, id);
  const override = chain.find((theme) => name in theme.overrides)?.overrides[name];
  return override ?? value[base] ?? value.light;
};

import { useState } from "react";

export const useControllableState = <Value>({
  value,
  defaultValue,
  onChange
}: {
  value: Value | undefined;
  defaultValue: Value;
  onChange?: (value: Value) => void;
}) => {
  const [internal, setInternal] = useState(defaultValue);
  const current = value === undefined ? internal : value;
  const setValue = (next: Value) => {
    if (value === undefined) setInternal(next);
    if (next !== current) onChange?.(next);
  };
  return [current, setValue] as const;
};

import {
  type CSSProperties,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState
} from "react";

export const useFlowTransition = (index: number) => {
  const [reduced, setReduced] = useState(
    () =>
      typeof window !== "undefined" &&
      Boolean(window.matchMedia?.("(prefers-reduced-motion: reduce)").matches)
  );
  const [height, setHeight] = useState<number>();
  const [ready, setReady] = useState(false);
  const [node, setNode] = useState<HTMLElement | null>(null);
  const [travel, setTravel] = useState<{ index: number; direction: "forward" | "back" }>({
    index,
    direction: "forward"
  });
  const intendedDirection = useRef<"forward" | "back" | undefined>(undefined);
  if (travel.index !== index) {
    setTravel({
      index,
      direction: intendedDirection.current ?? (index > travel.index ? "forward" : "back")
    });
    intendedDirection.current = undefined;
  }
  useEffect(() => {
    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    const change = () => setReduced(Boolean(query?.matches));
    query?.addEventListener("change", change);
    return () => query?.removeEventListener("change", change);
  }, []);
  const measure = useCallback((element: HTMLElement | null) => setNode(element), []);
  useLayoutEffect(() => {
    if (!node) return undefined;
    const update = () => {
      if (node.offsetHeight > 0) setHeight(node.offsetHeight);
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(node);
    const frame =
      typeof requestAnimationFrame === "function"
        ? requestAnimationFrame(() => setReady(true))
        : undefined;
    if (frame === undefined) setReady(true);
    return () => {
      observer.disconnect();
      if (frame !== undefined) cancelAnimationFrame(frame);
    };
  }, [node]);
  let style: CSSProperties = {};
  if (reduced) style = { transition: "none" };
  else if (height !== undefined) style = { height };
  return {
    measure,
    style,
    ready,
    reduced,
    direction: travel.direction,
    intend: (direction: "forward" | "back") => {
      intendedDirection.current = direction;
    }
  };
};

import * as React from "react";

export type IndicatorRect = { x: number; y: number; width: number; height: number };

export type MeasuredIndicatorOptions = {
  /** The positioned container the indicator sits in. */
  listRef: React.RefObject<HTMLElement | null>;
  /** Matches the one item that is currently selected. */
  activeSelector: string;
  /** Matches every item whose size can move the indicator. */
  itemSelector: string;
  /** Overrides the active item's own box, for an indicator that spans more than the item. */
  rect?: (active: HTMLElement, list: HTMLElement) => IndicatorRect;
  /** Runs after each measure, once the active item is known. */
  onMeasure?: (list: HTMLElement, active: HTMLElement | null, context: MeasureContext) => void;
  /** Re-runs the observers when the item set changes. */
  watch?: unknown;
  /** Skips all measuring and observing while false. */
  enabled?: boolean;
};

export type MeasureContext = { reveal: boolean; instant: boolean };

export type IndicatorState = IndicatorRect & { visible: boolean; instant: boolean };

const hidden: IndicatorState = { x: 0, y: 0, width: 0, height: 0, visible: false, instant: true };

/**
 * Measures the selected item and returns the box an indicator should slide to.
 * It snaps on the first measure, on resize and when fonts load, so nothing animates on mount.
 */
export function useMeasuredIndicator({
  listRef,
  activeSelector,
  itemSelector,
  rect,
  onMeasure,
  watch,
  enabled = true
}: MeasuredIndicatorOptions) {
  const [state, setState] = React.useState<IndicatorState>(hidden);
  const instant = React.useRef(true);
  const placed = React.useRef(false);
  const latest = React.useRef({ rect, onMeasure });
  latest.current = { rect, onMeasure };

  const measure = React.useCallback(
    (reveal = false) => {
      const list = listRef.current;
      if (!list) return;
      const active = list.querySelector<HTMLElement>(activeSelector);
      latest.current.onMeasure?.(list, active, { reveal, instant: instant.current });
      if (!active) {
        setState((current) =>
          current.visible ? { ...current, visible: false, instant: false } : current
        );
        return;
      }
      const box = latest.current.rect?.(active, list) ?? {
        x: active.offsetLeft,
        y: active.offsetTop,
        width: active.offsetWidth,
        height: active.offsetHeight
      };
      setState({ ...box, visible: true, instant: instant.current });
    },
    [listRef, activeSelector]
  );

  React.useLayoutEffect(() => {
    const list = listRef.current;
    if (!enabled || !list) return undefined;
    const snap = () => {
      instant.current = true;
      measure(true);
      instant.current = false;
    };
    if (placed.current) measure(true);
    else snap();
    placed.current = true;
    const observer = new MutationObserver(() => measure(true));
    observer.observe(list, { attributes: true, subtree: true, attributeFilter: ["data-state"] });
    const resize = new ResizeObserver(snap);
    resize.observe(list);
    list.querySelectorAll(itemSelector).forEach((item) => resize.observe(item));
    document.fonts?.addEventListener("loadingdone", snap);
    return () => {
      observer.disconnect();
      resize.disconnect();
      document.fonts?.removeEventListener("loadingdone", snap);
    };
  }, [listRef, itemSelector, measure, watch, enabled]);

  return { state, measure };
}

import * as React from "react";

export type OptionCreateHandler = (
  query: string,
  context: { signal: AbortSignal }
) => void | Promise<void>;
export function useOptionCreation(
  onCreate: OptionCreateHandler | undefined,
  onSuccess: () => void
) {
  const [creating, setCreating] = React.useState(false);
  const [error, setError] = React.useState("");
  const generation = React.useRef(0);
  const request = React.useRef<AbortController | null>(null);
  const cancel = React.useCallback(() => {
    generation.current += 1;
    request.current?.abort();
    request.current = null;
    setCreating(false);
    setError("");
  }, []);
  React.useEffect(
    () => () => {
      generation.current += 1;
      request.current?.abort();
    },
    []
  );
  const create = async (query: string) => {
    if (!onCreate) return;
    request.current?.abort();
    const controller = new AbortController();
    request.current = controller;
    generation.current += 1;
    const turn = generation.current;
    setCreating(true);
    setError("");
    try {
      await onCreate(query, { signal: controller.signal });
      if (turn === generation.current && !controller.signal.aborted) onSuccess();
    } catch (cause) {
      const aborted = cause instanceof DOMException && cause.name === "AbortError";
      if (turn === generation.current && !controller.signal.aborted && !aborted)
        setError("Could not create this option. Try again.");
    } finally {
      if (turn === generation.current) {
        request.current = null;
        setCreating(false);
      }
    }
  };
  return { creating, error, create, cancel };
}

import * as React from "react";

export function useOwnedEscape<ElementType extends HTMLElement>(
  ref: React.Ref<ElementType> | undefined,
  onEscapeKeyDown?: (event: KeyboardEvent) => void
) {
  const content = React.useRef<ElementType | null>(null);
  const attach = React.useCallback(
    (node: ElementType | null) => {
      content.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) {
        // eslint-disable-next-line no-param-reassign -- React attaches forwarded object refs by mutation.
        ref.current = node;
      }
    },
    [ref]
  );
  const handle = (event: KeyboardEvent) => {
    onEscapeKeyDown?.(event);
    if (event.defaultPrevented || !(event.target instanceof Element)) return;
    const owner = event.target.closest("[data-v4-escape-owner]");
    if (owner && content.current?.contains(owner)) event.preventDefault();
  };
  return { ref: attach, onEscapeKeyDown: handle };
}

