  --v4-hover: color-mix(in oklab, var(--v4-mix-ink) var(--v4-hover-mix), transparent);
  --v4-press: color-mix(in oklab, var(--v4-mix-ink) var(--v4-press-mix), transparent);
  --v4-control-surface: color-mix(in oklab, var(--v4-control) 30%, transparent);
  --v4-control-surface-hover: color-mix(in oklab, var(--v4-control) 50%, transparent);
  --v4-control-disabled-surface: color-mix(in oklab, var(--v4-control) 80%, transparent);
  --v4-control-invalid-border: var(--v4-bad);
  --v4-focus-ring: color-mix(in oklab, var(--v4-ink) var(--v4-opacity-nudge-dark), transparent);
  --v4-focus-ring-bad: color-mix(in oklab, var(--v4-bad) var(--v4-opacity-nudge-dark), transparent);
  --v4-action-danger-surface: color-mix(in oklab, var(--v4-bad) 20%, transparent);
  --v4-action-danger-hover: color-mix(in oklab, var(--v4-bad) 30%, transparent);
  --v4-action-ghost-hover: var(--v4-hover);
  --v4-action-outline-border: var(--v4-control);
  --v4-action-outline-surface: color-mix(in oklab, var(--v4-control) 30%, transparent);
  --v4-action-outline-hover: var(--v4-hover);
  --v4-choice-selected-surface: color-mix(in oklab, var(--v4-ink) 10%, transparent);
  --v4-choice-selected-border: color-mix(in oklab, var(--v4-ink) 20%, transparent);
  --v4-switch-off-surface: var(--v4-surface);
  --v4-switch-thumb: var(--v4-muted);
  --v4-switch-thumb-line: transparent;
  --v4-scroll-thumb: color-mix(in oklab, var(--v4-ink) 16%, transparent);
  --v4-scroll-thumb-hover: color-mix(in oklab, var(--v4-ink) 32%, transparent);
  --v4-avatar-blend: lighten;
  --v4-tab-label: var(--v4-muted);
  --v4-selected-surface: color-mix(in oklab, #555553 var(--v4-selected-mix), transparent);
  --v4-selected-border: #4a4a48;
  --v4-selected-ink: var(--v4-ink);
}
.v4[data-theme="peach"] {
  --v4-surface: #ffffff;
  --v4-inset: #ffffff;
  --v4-sidebar: #f5f3ee;
  --v4-tint: #faf8f4;
  --v4-line-soft: #e4ded5;
  --v4-line: #d5cdc2;
  --v4-faint: #85807a;
  --v4-mix-ink: #2e271d;
}
.v4[data-theme="pale"] {
  --v4-surface: #ffffff;
  --v4-inset: #f9f9fa;
  --v4-sidebar: #efeff0;
  --v4-tint: #f3f3f3;
  --v4-line-soft: #dadadd;
  --v4-line: #cbcbcf;
  --v4-faint: #828387;
}
.v4[data-theme="dark-alt"] {
  --v4-inset: #121213;
  --v4-sidebar: #09090a;
}

