  min-height: 0;
}
.v4 [data-slot="sheet-foot"] {
  display: flex;
  flex: none;
  flex-direction: column;
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.v4 :is([data-slot="sheet-scroll"]) {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.v4 [data-slot="sheet-head"] + [data-slot="sheet-scroll"] > [data-slot="sheet-body"]:first-child {
  padding-top: var(--v4-space-overlay-inset);
}
.v4 [data-slot="sheet-scroll"] > [data-slot="sheet-body"]:last-child {
  padding-bottom: var(--v4-space-overlay-inset);
}
.v4
  :is([data-slot="sheet-head"], [data-slot="dialog-head"])
  + :is([data-slot="sheet-scroll"], [data-slot="dialog-scroll"])[data-scroll-start-y] {
  --v4-fade-y-start: 0px;
}
.v4 :is([data-slot="sheet-scroll"], [data-slot="dialog-scroll"])[data-before-footer][data-scroll-end-y] {
  --v4-fade-y-end: 0px;
}

.v4 [data-slot="chart-tooltip"] .font-mono {
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
}

/* tw-animate otherwise falls back to its own timing. Base layer, so an explicit duration-* or ease-* utility still wins. */
@layer base {
  .v4 [class*="animate-in"],
  .v4 [class*="animate-out"] {
    --tw-duration: var(--v4-duration-fast);
    --tw-ease: var(--v4-ease-spring);
  }
}

/* Zero-specificity icon defaults: a component class or an explicit size wins. */
:where(.v4) :where([data-slot="icon"], svg.lucide) {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  stroke-width: var(--v4-stroke-icon);
}

/* Press: the control box never moves or resizes. Its label (text and icons) shrinks slightly on
   press and springs back; the pressed fill stays on the box. Reduced motion keeps the fill only. */
.v4 [data-press] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: inherit;
  min-width: 0;
  max-width: 100%;
  transform-origin: center;
  transition: scale var(--v4-duration-fast) var(--v4-ease-press);
}
.v4 :active:not(:disabled, [aria-disabled="true"]) > [data-press] {
  scale: 0.97;
}
@media (prefers-reduced-motion: reduce) {
  .v4 :active > [data-press] {
    scale: none;
  }
}

/* Edge-aware scroll fade (lib/scroll-edges.ts): only an edge with more content past it fades. */
.v4 [data-scroll-fade] {
  --v4-fade-y-start: 0px;
  --v4-fade-y-end: 0px;
  --v4-fade-x-start: 0px;
  --v4-fade-x-end: 0px;
}
.v4 [data-scroll-fade][data-scroll-start-y] {
  --v4-fade-y-start: var(--v4-size-scroll-fade);
}
.v4 [data-scroll-fade][data-scroll-end-y] {
  --v4-fade-y-end: var(--v4-size-scroll-fade);
}
.v4 [data-scroll-fade][data-scroll-start-x] {
  --v4-fade-x-start: var(--v4-size-scroll-fade);
}
.v4 [data-scroll-fade][data-scroll-end-x] {
  --v4-fade-x-end: var(--v4-size-scroll-fade);
}
.v4
  [data-scroll-fade]:is(
    [data-scroll-start-y],
    [data-scroll-end-y],
    [data-scroll-start-x],
    [data-scroll-end-x]
  ):not([data-scroll-edge="border"]) {
  mask-image: linear-gradient(
      to bottom,
      transparent,
      black var(--v4-fade-y-start),
      black calc(100% - var(--v4-fade-y-end)),
      transparent
    ),
    linear-gradient(
      to right,
      transparent,
      black var(--v4-fade-x-start),
      black calc(100% - var(--v4-fade-x-end)),
      transparent
    );
  mask-composite: intersect;
}
.v4 [data-scroll-fade][data-scroll-edge="border"][data-scroll-start-y] {
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.v4 [data-scroll-fade][data-scroll-edge="border"][data-scroll-end-y] {
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}

/* Keyboard focus on a selected option sits 1px further in, so selection plus focus never reads as a heavy box. */
.v4 [role="option"]:is([aria-selected="true"], [data-selected]):focus-visible {
  outline-offset: calc(-1 * var(--v4-size-focus-ring) - var(--v4-size-control-border));
}
